package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Particle;
import org.bukkit.entity.Enderman;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Player;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class FearfulEndermanBehaviour implements CompiledBehaviour {
    private static final PotionEffectType BLINDNESS = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:blindness");

    private static final Particle DRAGON_BREATH = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:dragon_breath");

    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final Particle WITCH = Registries.entry(RegistryKey.PARTICLE_TYPE, "minecraft:witch");

    private final MobContext context;

    private Cooldown cooldown;

    public FearfulEndermanBehaviour(MobContext context) {
        this.context = context;
        // node #34 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onHit(EntityDamageByEntityEvent event) {
        // node #7 event.hit
        // node #11 flow.branch
        // node #8 event.hit
        final Entity entity = event.getEntity();
        if (!(entity instanceof Player)) return;
        // node #10 living_entity.apply_effect
        // node #9 cast
        final Player cast = (entity instanceof Player ? (Player) entity : null);
        cast.addPotionEffect(new PotionEffect(BLINDNESS, (int) (7.0d * 20), 1, true, true));
        // node #12
    }

    @Override
    public void onNightEnd() {
        // node #20 mob.night_end
        // node #22 world.spawn_particle
        // node #21 mob.self
        final Enderman self = ((Enderman) this.context.entity());
        BukkitRuntime.particles(this.context, self.getWorld(), DRAGON_BREATH, self.getEyeLocation(), 10, 1.5d, 1.0d, 1.5d, Float.valueOf((float) 1.0d));
        // node #23
    }

    @Override
    public void onTick() {
        // node #41 mob.tick
        // node #46 flow.branch
        // node #42 mob.self
        final Enderman self = ((Enderman) this.context.entity());
        if (self.getTarget() == null) {
            // node #45 flow.branch
            // node #43 world.nearest_player
            final Player player = BukkitRuntime.nearestPlayer(self.getLocation(), 16.0d, true);
            if (player != null) {
                // node #44 mob.mutate
                self.setTarget(player);
            }
        }
        // node #49 flow.branch
        // node #47 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(250.0d));
        if (!cooldown) return;
        // node #48 world.spawn_particle
        BukkitRuntime.particles(this.context, self.getWorld(), WITCH, self.getEyeLocation(), 10, 1.5d, 1.0d, 1.5d, null);
        // node #50
    }
}
